using System;using System.IO;using UnityEngine;
namespace Vanta.Save{[Serializable]public sealed class SaveData{public Vector3 playerPosition;public int cash;public int wantedLevel;public float timeOfDay;public string activeMission;}public sealed class SaveSystem:MonoBehaviour{public string SlotPath(string slot)=>Path.Combine(Application.persistentDataPath,"vanta_"+slot+".json");public void Save(string slot,SaveData data){if(data==null)return;File.WriteAllText(SlotPath(slot),JsonUtility.ToJson(data,true));}public SaveData Load(string slot){var p=SlotPath(slot);return File.Exists(p)?JsonUtility.FromJson<SaveData>(File.ReadAllText(p)):null;}public bool Exists(string slot)=>File.Exists(SlotPath(slot));}}